param([Parameter(Mandatory=$true)][int]$ParentProcessId,[Parameter(Mandatory=$true)][string]$PackagePath,[Parameter(Mandatory=$true)][string]$InstallDir,[Parameter(Mandatory=$true)][string]$ApplicationPath,[Parameter(Mandatory=$true)][string]$SuccessMarker,[Parameter(Mandatory=$true)][string]$TargetVersion)
$ErrorActionPreference='Stop';$transaction=Split-Path -Parent $SuccessMarker;$backup=Join-Path $transaction 'backup';$staging=Join-Path $transaction 'staging';$log=Join-Path (Split-Path -Parent (Split-Path -Parent $transaction)) 'update.log'
function Log([string]$m){Add-Content -LiteralPath $log -Value "[$([DateTime]::Now.ToString('O'))] $m" -Encoding UTF8}
function CopyTree([string]$s,[string]$d){New-Item -ItemType Directory -Path $d -Force|Out-Null;Get-ChildItem -LiteralPath $s -Force|Copy-Item -Destination $d -Recurse -Force}
try{New-Item -ItemType Directory -Path $transaction -Force|Out-Null;Log "Starting $TargetVersion";$deadline=[DateTime]::UtcNow.AddSeconds(90);while([DateTime]::UtcNow-lt$deadline-and(Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue)){Start-Sleep -Milliseconds 250};if(Get-Process -Id $ParentProcessId -ErrorAction SilentlyContinue){throw 'Luma did not close.'};Remove-Item $staging,$backup -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Path $staging,$backup -Force|Out-Null;Expand-Archive -LiteralPath $PackagePath -DestinationPath $staging -Force;if(-not(Test-Path(Join-Path $staging 'Luma.exe'))){throw 'Luma.exe missing.'};CopyTree $InstallDir $backup;CopyTree $staging $InstallDir;Remove-Item $SuccessMarker -Force -ErrorAction SilentlyContinue;$arg='"--update-complete-marker='+$SuccessMarker.Replace('"','')+'"';$new=Start-Process $ApplicationPath -ArgumentList $arg -WorkingDirectory $InstallDir -PassThru;$deadline=[DateTime]::UtcNow.AddSeconds(60);while([DateTime]::UtcNow-lt$deadline-and-not(Test-Path $SuccessMarker)){if($new.HasExited){break};Start-Sleep -Milliseconds 500;$new.Refresh()};if(-not(Test-Path $SuccessMarker)){throw 'Updated Luma did not confirm startup.'};Log 'Update successful';Remove-Item $PackagePath -Force -ErrorAction SilentlyContinue;Remove-Item $staging,$backup -Recurse -Force -ErrorAction SilentlyContinue;exit 0}catch{Log "Failed: $($_.Exception)";try{Get-Process Luma -ErrorAction SilentlyContinue|Where-Object{$_.Path-eq$ApplicationPath}|Stop-Process -Force -ErrorAction SilentlyContinue;Start-Sleep -Milliseconds 500;if(Test-Path $backup){Get-ChildItem $InstallDir -Force|Remove-Item -Recurse -Force;CopyTree $backup $InstallDir};Start-Process $ApplicationPath -WorkingDirectory $InstallDir|Out-Null}catch{Log "Rollback failed: $($_.Exception)"};exit 1}
